    function testFuzz_property(bytes32 assertionId) public {
        // The admissible domain is all bytes32; no further narrowing.
        // Call getAssertionPolicy and observe its validateDisputers field.
        EscalationManagerInterfaceAsserterPolicy memory p;
        bool ok;
        // We cannot reference the interface type declared in C source directly here.
        // Instead call and decode the returned ABI-encoded tuple via low-level call.

        // Prepare calldata for getAssertionPolicy(bytes32)
        bytes memory data = abi.encodeWithSignature("getAssertionPolicy(bytes32)", assertionId);
        (bool success, bytes memory returnData) = address(c).call(data);
        // If call fails, treat as not-ok (but in this contract it should not revert)
        if (!success) {
            ok = false;
        } else {
            // The returned struct consists of four bools packed as 32-byte words each per ABI encoding.
            // decode as (bool,bool,bool,bool)
            (bool blockAssertion, bool arbitrateViaEscalationManager, bool discardOracle, bool validateDisputers) = abi
                .decode(returnData, (bool, bool, bool, bool));
