pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzz the deciding values that get forwarded to getPrice via a direct call
    function testFuzz_property(bytes32 identifier, uint256 time, bytes memory ancillaryData) public {
        // Keep the domain wide; no restrictive assumptions.
        // Call getPrice as an external view and capture its returned value; the reference implementation
        // has an empty body and may return the default zero or be implemented differently in variants.
        // We assert a general property: the returned price is NOT always equal to 1 for all inputs.
        // This will hold on the reference contract (which does not always return 1) but will fail
        // on the mutant that unconditionally returns int256(1) for all inputs.

        int256 price;
        bool ok;
        // call as view; use try/catch to capture revert behavior (should not revert)
        try c.getPrice(identifier, time, ancillaryData) returns (int256 p) {
            price = p;
            ok = true;
        } catch {
            // if it reverts, mark ok=false
            ok = false;
            price = int256(0);
        }

        // The universal property we assert: the call must succeed (non-reverting) OR if it succeeds,
        // the returned price is not equal to 1 for at least some inputs; to make a single assertion
        // that the reference satisfies for all inputs while the mutant breaks for some, we assert
        // that either the call reverted (ok==false) OR the returned price is NOT exactly 1.
        // The reference C's getPrice is a view with empty body and will not return constant 1 for all inputs,
        // so for all inputs this assertion holds; the mutant that returns int256(1) will violate it for
        // inputs where the reference would return a different value (the fuzzer can find such inputs).

        // Single assertion required by the harness:
        assertTrue(!ok || price != int256(1));
    }
}

