pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    // We will act as the optimisticAsserter (constructor set as address(this) in setUp)
    // The test fuzzes the three parameters that getPrice accepts.
    function setUp() public { c = new C(address(this)); }

    // Fuzzed parameters: identifier, time, ancillaryData
    function testFuzz_property(bytes32 identifier, uint256 time, bytes memory ancillaryData) public {
        // Keep domain wide: no restrictive vm.assume. However, to avoid extremely large ancillaryData that
        // may blow memory in some harnesses, bound its length moderately while still allowing varied inputs.
        // We re-encode ancillaryData if it's huge via a simple truncation to keep fuzz wide.
        if (ancillaryData.length > 1024) {
            bytes memory truncated = new bytes(1024);
            for (uint256 i = 0; i < 1024; i++) truncated[i] = ancillaryData[i];
            ancillaryData = truncated;
        }

        // The reference contract's getPrice is declared `view virtual` without implementation (implicitly returns
        // no value). The optimisticAsserter is this test contract (address(this)). We exercise the pathway
        // through assertionDisputedCallback which in realistic implementations would call getPrice. Here we
        // simulate that the EscalationManager's getPrice would be queried by reading c.getPrice directly.
        // We call c.getPrice as the external observer would; since in the reference the function is an empty
        // view, calling it via try/catch should succeed (non-reverting) but produce a nondeterministic value.
        // The mutant returns constant 0 which we must detect. The invariant we assert: the getPrice call
        // invoked on c returns a nonzero int256 for all inputs on the reference; the mutant will allow 0
        // for some inputs, causing the assert to fail.

        bool ok;
        int256 price;
        try c.getPrice(identifier, time, ancillaryData) returns (int256 p) {
            ok = true;
            price = p;
        } catch {
            // In the reference this should not revert; treat revert as failure of the invariant
            ok = false;
            price = int256(0);
        }

        // Single assertion observing c: on the correct contract this MUST hold for all inputs
        // (we assert that getPrice call succeeded and returned a nonzero int256). The mutant that
        // returns int256(0) for some inputs will violate this assertion for those inputs.
        assertTrue(ok && price != int256(0));
    }
}

