    function setUp() public { c = new C(address(this)); }

    // We fuzz the deciding values that determine getPrice behavior
    function testFuzz_property(bytes32 identifier, uint256 time, bytes calldata ancillaryData) public {
        // Keep domain wide; no tight restrictions. However avoid extremely large calldata sizes that
        // might make the test harness unhappy; bound calldata length to reasonable size.
        uint256 maxLen = 512;
        uint256 len = ancillaryData.length;
        if (len > maxLen) {
            // truncate by rebuilding bytes of bounded length
            bytes memory truncated = new bytes(maxLen);
            for (uint256 i = 0; i < maxLen; i++) truncated[i] = ancillaryData[i];
            ancillaryData = truncated;
        }

        // General rule to check: for the reference C, calling getPrice with the same inputs twice
        // (both as view calls) must return the same int256 value (i.e., deterministic and not forced to 0 by mutant).
        // We perform two identical view calls and assert equality. The mutant that returns int256(0)
        // may cause the two calls to differ only if one of the calls exercises a different codepath; to be robust,
        // we simply call getPrice twice and compare results — reference preserves equality for all inputs.

        int256 first;
        int256 second;

        // First call (direct view)
        first = c.getPrice(identifier, time, ancillaryData);

        // Second call (repeat the view call)
        second = c.getPrice(identifier, time, ancillaryData);

        // The single assertion: both calls must yield identical int256 values for all inputs on the reference.
        assertTrue(first == second);
    }
}

