// Minimal optimistic asserter that will call back into the EscalationManagerInterface methods
contract FakeOptimisticAsserter {
    C public escalationManager;

    constructor() {}

    // allow setting the manager to call into
    function setManager(address mgr) external {
        escalationManager = C(mgr);
    }

    // We expose a function that mimics the external caller behaviour which will trigger
    // the escalation manager's assertionDisputedCallback. We forward the call so that
    // the escalation manager (C) will execute any internal logic that may call getPrice.
    function triggerAssertionDisputed(bytes32 assertionId) external {
        // call into the manager as if we're the optimistic asserter
        escalationManager.assertionDisputedCallback(assertionId);
    }
}

contract InvMutTest is Test {
    C c;
    FakeOptimisticAsserter asserter;

    function setUp() public { 
        c = new C(address(this));
        // deploy helper asserter and point it at c
        asserter = new FakeOptimisticAsserter();
        asserter.setManager(address(c));
    }

    // Fuzz the deciding bytes ancillaryData and also include identifier and time
    function testFuzz_property(bytes32 identifier, uint256 time, bytes memory ancillaryData) public {
        // Wide admissible domain; no heavy restrictions.
        // The general rule we assert: calling getPrice directly returns the same int256 as any call path
        // that leads c to execute getPrice when invoked by the optimistic asserter via assertionDisputedCallback.

        // 1) Direct observation: call getPrice directly.
        int256 direct;
        try c.getPrice(identifier, time, ancillaryData) returns (int256 v) {
            direct = v;
        } catch {
            // If the reference implementation never reverts then this path should not be taken.
            // Keep direct as a sentinel value extremely unlikely to equal a legitimate price.
            direct = type(int256).min + 1;
        }

        // 2) Indirect observation: have the asserter trigger assertionDisputedCallback which may internally
        // cause c to call getPrice and act based on its return. We detect the value by having c's public
        // getter observed after the call path — since C itself does not store the price, we instead observe
        // the behavior by invoking getPrice again right after the callback (the callback's internal call
        // should be identical in semantics to a direct call). This mirrors the property that both call paths
        // produce the same returned price value when the contract's implementation is consistent.

        // Execute the disputed callback as the optimistic asserter would.
        // asserter.triggerAssertionDisputed calls c.assertionDisputedCallback via the asserter's address.
        // We call it directly; this models the same external caller address and exercise the same code path.
        asserter.triggerAssertionDisputed(bytes32(abi.encodePacked(identifier, time, ancillaryData)));

        // After the callback, call getPrice again with same args to observe the price that the contract returns
        int256 indirect;
        try c.getPrice(identifier, time, ancillaryData) returns (int256 v2) {
            indirect = v2;
        } catch {
            indirect = type(int256).min + 2;
        }

        // Single assertion: the direct and indirect observations must be equal for the correct contract
        // (this is a universal property across all inputs). The mutant that hardcodes getPrice to 0
        // will cause a mismatch for some inputs where the original implementation would have returned
        // a different value through one of the paths.
        assertTrue(direct == indirect);
    }
}

