        // The universal property we assert: for the reference C, getPrice never returns a non-zero int256 payload observable via staticcall.
        // Therefore assertTrue(returned == 0). The mutant will produce non-zero returned for some identifier (e.g., any non-zero id),
        // causing the test to fail for those fuzz inputs.
        assertTrue(returned == 0);
    }
